SELECT datasetkey, FLOOR(decimallatitude * 10) AS lat10, FLOOR(decimallongitude * 10) AS lon10, "month", v_scientificname, occurrence.gbif_classification.specieskey AS specieskey, COUNT(*) AS n FROM occurrence WHERE occurrence.gbif_classification.classkey = '212' AND hascoordinate = TRUE AND hasgeospatialissues = FALSE AND level0gid IS NULL AND decimallatitude >= -10 AND decimallatitude <= 90 AND decimallongitude >= -180 AND decimallongitude <= -40 AND datasetkey IN ('4fa7b334-ce0d-4e88-aaae-2e0c138d049e', '50c9509d-22c7-4a22-a47d-8c48425ef4a7') AND occurrencestatus = 'PRESENT' GROUP BY datasetkey, FLOOR(decimallatitude * 10), FLOOR(decimallongitude * 10), "month", v_scientificname, occurrence.gbif_classification.specieskey
